def copy_existing_assignees(apps, schema_editor):
    """Köhnə təkli icraçıları (Ticket.assignee, TicketDepartment.assignee) yeni cədvələ köçürür."""
    Ticket = apps.get_model('tickets', 'Ticket')
    TicketDepartment = apps.get_model('tickets', 'TicketDepartment')
    TicketAssignee = apps.get_model('tickets', 'TicketAssignee')
    in_progress = {'in_progress', 'waiting', 'resolved', 'closed'}

    def status_for(ticket):
        return 'in_progress' if ticket.status in in_progress else 'assigned'

    for link in TicketDepartment.objects.exclude(assignee__isnull=True).select_related('ticket'):
        TicketAssignee.objects.get_or_create(
            ticket_id=link.ticket_id, user_id=link.assignee_id,
            defaults={'department_id': link.department_id,
                      'status': 'done' if link.status == 'done' else status_for(link.ticket)},
        )
    for ticket in Ticket.objects.exclude(assignee__isnull=True):
        TicketAssignee.objects.get_or_create(
            ticket_id=ticket.id, user_id=ticket.assignee_id,
            defaults={'status': status_for(ticket)},
        )


